head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var info1 = $p.getMetaValue("meta_LPI");
    var info2 = $p.getMetaValue("meta_DPI");
    var logStr = "meta_DPI : " + info1 + " --- meta_DPI : " + info2
    $p.log(logStr);
    textarea1.setValue(logStr);
};
scwin.trigger2_onclick = function(e) {
    var info = WebSquare.util.serialize({
        "method": "HEADBODY"
    });
    $p.log(info);
    textarea1.setValue(info);
};
scwin.init = function() {
    $p.log($p.id + "scwin.init");
}
